-- Pupitre : mise à jour d'une base de développement, écrite le 28/11/2026 à 11:28 depuis la base de référence (Pupitre 1.1).
-- État : migrations passées jusqu'à « 012-apercus-depots-veille-courrier » ; site publié en version 20261128a.
--
-- CE QUE FAIT CE SCRIPT
--   Il remplace 47 tables par celles de la base de référence, structure et contenu : tout ce qui a été saisi
--   dans ces tables sur le poste d'arrivée est perdu.
--   Il ne touche pas aux comptes (comptes, liens_connexion, tentatives_connexion) : vous gardez votre compte et votre mot de passe.
--   Ces tables ne sont créées, vides, que si elles manquent ; une colonne ajoutée depuis par une migration leur est posée.
--   7 tables arrivent vides, parce qu'elles tiennent à un poste ou à des personnes et n'ont pas leur place dans git :
--   apercus, apercus_validations, courriers, depots, depots_fichiers, lettre_inscrits, taches.
--
-- POUR L'APPLIQUER, après « git pull », depuis le dossier pierrebleuse :
--   php pupitre/sql/restaurer.php mise-a-jour-base/pupitre-mise-a-jour-20261128.sql --oui
--   (la base d'avant est d'abord sauvegardée dans pupitre/stockage/sauvegardes/), puis : php pupitre/sql/migrer.php --etat
--   Sans ligne de commande : importer ce fichier dans la base de Pupitre avec phpMyAdmin. MySQL 8 est requis.
--   Ensuite, dans Pupitre : « Le site » doit dire « aucun écart » (les fichiers du site viennent du même commit).
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `alertes`;
CREATE TABLE `alertes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `niveau` enum('prioritaire','action','info') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'action' COMMENT 'alerte prioritaire, action à traiter, information',
  `cle` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'type et objet : une alerte par sujet',
  `message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `lien` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `etat` enum('ouverte','reportee','ignoree') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ouverte',
  `reportee_au` date DEFAULT NULL,
  `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `maj_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cle` (`cle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `alertes` VALUES (3,'proche','prioritaire','proche:c8','« Orquesta y Coro Nacionales de España », 28 novembre 2026 : il manque lien source (page de l\'organisateur), lien de billetterie ou page de l\'organisateur.','page=concert&id=8','ouverte',NULL,'2026-11-13 10:37:45','2026-11-28 06:54:21'),(4,'proche','prioritaire','proche:c9','« In Between trance », 3 décembre 2026 : il manque lien source (page de l\'organisateur), lien de billetterie ou page de l\'organisateur.','page=concert&id=9','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(5,'extrait','info','extrait:aucun','Aucun extrait de l\'agence n\'a encore été importé.','page=imports','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(6,'vide','info','vide:disques','Albums sans lien d\'écoute ni de commande : Unsuk Chin, Viola Concertos, Ligeti.','page=disques','ouverte',NULL,'2026-11-13 10:37:45','2026-11-28 10:49:38'),(7,'vide','info','vide:articles','Articles sans citation : Le Monde, The Guardian, Gramophone.','page=presse','ouverte',NULL,'2026-11-13 10:37:45','2026-11-27 19:30:29'),(8,'vide','info','vide:telechargements','Téléchargements « à venir » : Biography, in French, Biography, in English, Photographs, Visual identity.','page=contenu&type=telechargements','ouverte',NULL,'2026-11-13 10:37:45','2026-11-28 10:49:21'),(17,'proche','prioritaire','proche:c10','« Christmas Concert », 18 décembre 2026 : il manque lien source (page de l\'organisateur), lien de billetterie ou page de l\'organisateur.','page=concert&id=10','ouverte',NULL,'2026-11-27 13:56:53','2026-11-28 10:49:21'),(25,'vide','info','vide:exemples','8 faux articles de maquette sont dans la revue de presse : à supprimer avant la mise en production.','page=presse','ouverte',NULL,'2026-11-27 15:06:14','2026-11-27 19:30:29'),(36,'communication','action','communication:sans-action','3 concerts annoncés dans les 30 jours n\'ont aucune action de communication enregistrée : « Orquesta y Coro Nacionales de España » (28 novembre), « In Between trance » (3 décembre), « Christmas Concert » (18 décembre).','page=editorial#concerts','ouverte',NULL,'2026-11-27 19:30:29','2026-11-28 10:54:10'),(44,'depot','info','depot:sans9','« In Between trance » (3 décembre 2026) n\'a pas de contact communication : personne ne sera invité à déposer des images.','page=concert&id=9','ouverte',NULL,'2026-11-28 10:49:21','2026-11-28 10:49:21');
DROP TABLE IF EXISTS `annuaire`;
CREATE TABLE `annuaire` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `categorie` enum('orchestre','ensemble','salle','festival','soliste','compositeur','maison_de_disques','media','photographe','producteur','agence') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom_provisoire` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'le vrai nom reste à fournir : le site n''affiche que la ville',
  `autres_noms` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'un par ligne',
  `ville_en` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `pays_en` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `langue` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'média : langue principale',
  `latitude` decimal(8,5) DEFAULT NULL,
  `longitude` decimal(8,5) DEFAULT NULL,
  `verifie` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ville et coordonnées de référence vérifiées',
  `fuseau` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `site` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `premiere_collaboration` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'AAAA, AAAA-MM ou AAAA-MM-JJ',
  `mots_diese` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `credit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `logo_id` int unsigned DEFAULT NULL COMMENT 'médiathèque',
  `typo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'média sans logo : traitement typographique de son nom sur le site',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modifie_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `categorie` (`categorie`),
  KEY `nom` (`nom`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
