DROP TABLE IF EXISTS `articles`;
CREATE TABLE `articles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `cle` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'critique_concert, critique_album, portrait, interview, actualite, autre',
  `media_id` int unsigned DEFAULT NULL COMMENT 'annuaire : le titre de presse, qui porte aussi le logo',
  `titre_en` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `chapeau_en` text COLLATE utf8mb4_unicode_ci,
  `auteur` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `date_article` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'AAAA-MM-JJ ou AAAA-MM ; vide si inconnue',
  `verbatim` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'cité dans sa langue',
  `langue` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `resume_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `infos_en` text COLLATE utf8mb4_unicode_ci COMMENT 'informations complémentaires',
  `lien` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `url_canonique` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `publie` tinyint(1) NOT NULL DEFAULT '1',
  `une` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'à la une : marque éditoriale, indépendante de la publication',
  `accueil` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'sélectionné pour la page d''accueil',
  `ordre_accueil` int NOT NULL DEFAULT '0',
  `largeur` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'sur l''accueil : 1, 2 ou 4 colonnes',
  `exemple` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'faux article de maquette, à supprimer avant la mise en production',
  `origine` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main' COMMENT 'main, url (importé d''une adresse), texte (texte collé)',
  `texte_source` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'texte de l''article récupéré ou collé : sert à vérifier les citations, ne sort jamais sur le site',
  `ordre` int NOT NULL DEFAULT '0',
  `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `articles` VALUES (1,'fanfare','',50,'On *Ravel Abroad*',NULL,'Colin Clarke','','“A simply astonishing disc.”','en','',NULL,'','',1,0,0,0,1,0,'main',NULL,0,'2026-11-27 14:39:18'),(2,'le-monde','',51,'Profile',NULL,'Pierre Gervasoni','2024-06-22','','fr','',NULL,'https://www.lemonde.fr/culture/article/2024/06/22/pierre-bleuse-directeur-musical-de-l-ensemble-intercontemporain-veut-faire-entendre-tout-ce-qui-se-passe-sur-la-planete_6242263_3246.html','',1,0,0,1,1,0,'main',NULL,1,'2026-11-27 14:39:18'),(3,'the-guardian','',52,'Review of the *Unsuk Chin* album',NULL,'Fiona Maddocks','2026-02-13','','en','',NULL,'https://www.theguardian.com/music/2026/feb/13/ensemble-intercontemporain-unsuk-chin-album-review-pierre-bleuse-samuel-favre-dimitri-vassilakis-gougalon-double-concerto','',1,0,0,2,1,0,'main',NULL,2,'2026-11-27 14:39:18'),(4,'gramophone','',53,'Review of the *Ligeti* album',NULL,'Richard Whitehouse','2024-06','','en','',NULL,'https://gramophone.co.uk/review/ligeti-concertos-and-chamber-music-bleuse','',1,0,0,3,1,0,'main',NULL,3,'2026-11-27 14:39:18'),(5,'exemple-contrepoint','',77,'Pierre Bleuse: clarity as a manifesto',NULL,'Claire Duvernay','2026-10-08','« Sous sa baguette, la partition la plus dense devient lisible comme une page d’écriture. »','fr','An interview with the music director of the Ensemble intercontemporain, between two rehearsals, on passing on today’s repertoire.',NULL,'https://example.com/contrepoint/pierre-bleuse','',1,0,1,0,4,1,'main',NULL,4,'2026-11-27 14:39:18'),(6,'exemple-the-score','',78,'Review of the *Ligeti* album',NULL,'Hannah Whitcombe','2026-09-19','“Precise without ever being cold, this is Ligeti with a pulse.”','en','The reviewer praises a reading of the concertos both rigorous and lyrical, served by a recording of great transparency.',NULL,'https://example.com/the-score/ligeti-review','',1,0,1,1,2,1,'main',NULL,5,'2026-11-27 14:39:18'),(7,'exemple-klangbild','',79,'A French conductor in Stuttgart',NULL,'Stefan Kranich','2026-07-02','„Ein Dirigent, der zuhört, bevor er gestaltet.“','de','A concert review with the SWR Symphonieorchester, in which the *Symphonie fantastique* regains its share of dream and unease.',NULL,'https://example.com/klangbild/stuttgart','',1,0,1,2,2,1,'main',NULL,6,'2026-11-27 14:39:18'),(8,'exemple-echo-lyrique','',80,'Prades, a festival that breathes',NULL,'Julien Morel','2026-08-14','« Le Festival Pablo Casals a trouvé en lui un hôte autant qu’un directeur. »','fr','A look back at the 2026 Pablo Casals Festival, its programme between chamber music and premieres, set in the abbey of Saint-Michel-de-Cuxa.',NULL,'https://example.com/echo-lyrique/prades-2026','',1,0,1,3,1,1,'main',NULL,7,'2026-11-27 14:39:18'),(9,'exemple-mesures','',81,'*Répons*, with space as an instrument',NULL,'Margot Lefèvre','2026-05-27','« Une architecture sonore qui tourne autour de l’auditeur, et le tient en haleine. »','fr','At the Philharmonie de Paris, the Ensemble intercontemporain revives Pierre Boulez’s emblematic work in a spatialised set-up.',NULL,'https://example.com/mesures/repons','',1,0,1,4,1,1,'main',NULL,8,'2026-11-27 14:39:18'),(10,'exemple-podium','',82,'A dazzling Unsuk Chin evening',NULL,'Daniel Ashworth','2026-03-11','“Every colour in its place, every gesture with a purpose.”','en','The launch concert of the Unsuk Chin album, between the soloists’ virtuosity and the ensemble’s cohesion.',NULL,'https://example.com/podium/unsuk-chin','',1,0,1,5,1,1,'main',NULL,9,'2026-11-27 14:39:18'),(11,'exemple-gazette','',83,'Ravel, from one continent to another',NULL,'Antoine Valcourt','2026-01-23','« Un Ravel voyageur, d’une élégance qui n’exclut jamais le risque. »','fr','The *Ravel Abroad* album sheds light on the echoes of America and Spain in the composer’s work.',NULL,'https://example.com/gazette/ravel-abroad','',1,0,1,6,1,1,'main',NULL,10,'2026-11-27 14:39:18'),(12,'exemple-nordisk','',84,'Five seasons in Odense',NULL,'Ida Halvorsen','2025-12-05','“He leaves an orchestra that plays with one breath.”','en','An assessment of his tenure as Chief Conductor of the Odense Symphony Orchestra, from the great symphonies to commissions from Danish composers.',NULL,'https://example.com/nordisk/odense','',1,0,0,7,1,1,'main',NULL,11,'2026-11-27 14:39:18');
DROP TABLE IF EXISTS `articles_citations`;
CREATE TABLE `articles_citations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `article_id` int unsigned NOT NULL,
  `texte` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'la citation, dans sa langue et sa formulation d''origine, avec ses guillemets',
  `langue` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'langue d''origine de la citation',
  `traduction_en` text COLLATE utf8mb4_unicode_ci COMMENT 'traduction dans la langue de rédaction ; vide si la citation est déjà dans cette langue',
  `principale` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'la citation mise en avant : une par article',
  `verifiee` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 : proposée par l''IA, formulation à vérifier dans l''article',
  `ordre` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `article_id` (`article_id`,`ordre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `articles_citations` VALUES (1,1,'“A simply astonishing disc.”','en',NULL,1,1,0),(2,5,'« Sous sa baguette, la partition la plus dense devient lisible comme une page d’écriture. »','fr',NULL,1,1,0),(3,6,'“Precise without ever being cold, this is Ligeti with a pulse.”','en',NULL,1,1,0),(4,7,'„Ein Dirigent, der zuhört, bevor er gestaltet.“','de',NULL,1,1,0),(5,8,'« Le Festival Pablo Casals a trouvé en lui un hôte autant qu’un directeur. »','fr',NULL,1,1,0),(6,9,'« Une architecture sonore qui tourne autour de l’auditeur, et le tient en haleine. »','fr',NULL,1,1,0),(7,10,'“Every colour in its place, every gesture with a purpose.”','en',NULL,1,1,0),(8,11,'« Un Ravel voyageur, d’une élégance qui n’exclut jamais le risque. »','fr',NULL,1,1,0),(9,12,'“He leaves an orchestra that plays with one breath.”','en',NULL,1,1,0);
DROP TABLE IF EXISTS `articles_concerts`;
CREATE TABLE `articles_concerts` (
  `article_id` int unsigned NOT NULL,
  `concert_id` int unsigned NOT NULL,
  PRIMARY KEY (`article_id`,`concert_id`),
  KEY `concert_id` (`concert_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `articles_disques`;
CREATE TABLE `articles_disques` (
  `article_id` int unsigned NOT NULL,
  `disque_id` int unsigned NOT NULL,
  PRIMARY KEY (`article_id`,`disque_id`),
  KEY `disque_id` (`disque_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `blocs`;
CREATE TABLE `blocs` (
  `cle` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'identifiant de la section dans la page : agenda, visuel-1…',
  `nom` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'nom du bloc dans Pupitre',
  `parent` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'section qui le contient, s''il n''est qu''une partie de section',
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  `masquable` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 : toujours affiché (pied de page et ses liens légaux)',
  `parametres` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'JSON : réglages propres au bloc',
  `ordre` int NOT NULL DEFAULT '0',
  `modifie_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`cle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
