CREATE TABLE IF NOT EXISTS `liens_connexion` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `compte_id` int unsigned NOT NULL,
  `jeton` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-256 du jeton : le jeton lui-même n''est jamais conservé',
  `objet` enum('connexion','mot_de_passe') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `expire_le` datetime NOT NULL,
  `utilise_le` datetime DEFAULT NULL,
  `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `jeton` (`jeton`),
  KEY `compte_id` (`compte_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET @pupitre_maj = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `liens_connexion` ADD COLUMN `id` int unsigned NOT NULL AUTO_INCREMENT', 'DO 0') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'liens_connexion' AND column_name = 'id');
PREPARE pupitre_maj FROM @pupitre_maj;
EXECUTE pupitre_maj;
DEALLOCATE PREPARE pupitre_maj;
SET @pupitre_maj = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `liens_connexion` ADD COLUMN `compte_id` int unsigned NOT NULL', 'DO 0') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'liens_connexion' AND column_name = 'compte_id');
PREPARE pupitre_maj FROM @pupitre_maj;
EXECUTE pupitre_maj;
DEALLOCATE PREPARE pupitre_maj;
SET @pupitre_maj = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `liens_connexion` ADD COLUMN `jeton` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT \'SHA-256 du jeton : le jeton lui-même n\'\'est jamais conservé\'', 'DO 0') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'liens_connexion' AND column_name = 'jeton');
PREPARE pupitre_maj FROM @pupitre_maj;
EXECUTE pupitre_maj;
DEALLOCATE PREPARE pupitre_maj;
SET @pupitre_maj = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `liens_connexion` ADD COLUMN `objet` enum(\'connexion\',\'mot_de_passe\') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL', 'DO 0') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'liens_connexion' AND column_name = 'objet');
PREPARE pupitre_maj FROM @pupitre_maj;
EXECUTE pupitre_maj;
DEALLOCATE PREPARE pupitre_maj;
SET @pupitre_maj = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `liens_connexion` ADD COLUMN `expire_le` datetime NOT NULL', 'DO 0') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'liens_connexion' AND column_name = 'expire_le');
PREPARE pupitre_maj FROM @pupitre_maj;
EXECUTE pupitre_maj;
DEALLOCATE PREPARE pupitre_maj;
SET @pupitre_maj = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `liens_connexion` ADD COLUMN `utilise_le` datetime DEFAULT NULL', 'DO 0') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'liens_connexion' AND column_name = 'utilise_le');
PREPARE pupitre_maj FROM @pupitre_maj;
EXECUTE pupitre_maj;
DEALLOCATE PREPARE pupitre_maj;
SET @pupitre_maj = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `liens_connexion` ADD COLUMN `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP', 'DO 0') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'liens_connexion' AND column_name = 'cree_le');
PREPARE pupitre_maj FROM @pupitre_maj;
EXECUTE pupitre_maj;
DEALLOCATE PREPARE pupitre_maj;
DROP TABLE IF EXISTS `maisons`;
CREATE TABLE `maisons` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `cle` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom_en` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `ordre` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `cle` (`cle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `maisons` VALUES (1,'eic','Ensemble intercontemporain',0),(2,'odense','Orchestre symphonique d\'Odense',1),(3,'prades','Festival Pablo Casals',2),(4,'invite','Chef invité',3);
DROP TABLE IF EXISTS `medias`;
CREATE TABLE `medias` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `type` enum('image','son','video','document') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fichier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'nom dans stockage/medias/ ; vide si le fichier ne vit que dans le site',
  `chemin_site` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'chemin dans le site une fois publié (assets/…)',
  `url_externe` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'adresse externe (image, vidéo, YouTube) : aucun fichier n''est alors copié',
  `nom_origine` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `titre` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'nom du média dans Pupitre',
  `mime` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `taille` int unsigned NOT NULL DEFAULT '0',
  `largeur` int unsigned DEFAULT NULL,
  `hauteur` int unsigned DEFAULT NULL,
  `alt_en` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `credit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `droits` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'droits d''usage, en texte libre',
  `droits_valides` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 : droits d''utilisation à confirmer, le média ne sort pas sur le site',
  `cree_par` int unsigned DEFAULT NULL,
  `cree_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
