DROP TABLE IF EXISTS `textes`;
CREATE TABLE `textes` (
  `cle` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'description, citation, biographie, saison, lettre, credit',
  `en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `modifie_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`cle`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `textes` VALUES ('biographie','Pierre Bleuse is Music Director of the Ensemble intercontemporain and Artistic Director of the Pablo Casals Festival in Prades. Chief Conductor of the Odense Symphony Orchestra from 2021 to 2026, he is a guest of orchestras including the Royal Concertgebouw Orchestra, the London Philharmonic Orchestra, the Orchestre de Paris and the Tokyo Symphony Orchestra.\n\nA violinist by training, he brings the same attention to the great symphonic repertoire and to the music of today, letting works speak to one another rather than setting them apart.','2026-11-13 10:37:45'),('citation','“The further I progress, the freer I feel”','2026-11-28 10:58:27'),('credit','Website in progress · music: Tchaikovsky, Symphony No. 6, IV, Musopen (public domain); Berlioz, *Symphonie fantastique*, SWR Symphonieorchester (ARD Klassik); *The Centenary of Pierre Boulez*, Ensemble intercontemporain & Friends (ARTE Concert)','2026-11-27 15:21:39'),('description','Official website of conductor Pierre Bleuse: concert schedule, biography, recordings, press, contacts.','2026-11-13 10:37:45'),('lettre','The month\'s concerts and news, once a month.','2026-11-13 10:37:45'),('saison','2026/27 season','2026-11-13 10:37:45');
DROP TABLE IF EXISTS `traductions`;
CREATE TABLE `traductions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `objet` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'table de l''objet traduit',
  `objet_id` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'clé de la ligne : identifiant, ou clé texte',
  `champ` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `langue` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `texte` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `statut` enum('validee','proposee') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'validee' COMMENT 'proposee : proposée par l''IA, ne sort pas sur le site',
  `origine` enum('main','ia','reprise') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main',
  `empreinte` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'MD5 du texte de référence au moment de la traduction : s''il a changé, la traduction est à revoir',
  `modifie_le` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `objet` (`objet`,`objet_id`,`champ`,`langue`),
  KEY `langue` (`langue`,`statut`)
